 requires_external_compute=excluded.requires_external_compute, replaces_or_complements=excluded.replaces_or_complements,
 roles=excluded.roles, constraints=excluded.constraints, notes=excluded.notes, verified_at=excluded.verified_at, updated_at=now();

values ('kimi','Kimi / Moonshot AI','direct','discovered',true,'{"reasoning":true,"agents":true,"long_context":true,"coding":true}'::jsonb,'Candidate from LISTIA historical architecture. Runtime remains disabled until current API, pricing, privacy and benchmark are revalidated.',null)
on conflict (provider_key) do update set display_name=excluded.display_name,provider_type=excluded.provider_type,direct_api_available=excluded.direct_api_available,capabilities=excluded.capabilities,notes=excluded.notes,updated_at=now();

values ('kimi:direct','kimi','kimi','kimi_api',false,'not_configured',array['KIMI_API_KEY'],'unknown','{"mode":"direct"}'::jsonb)
on conflict (runtime_key) do update set provider_key=excluded.provider_key,execution_surface=excluded.execution_surface,adapter_key=excluded.adapter_key,credential_secret_names=excluded.credential_secret_names,configuration=excluded.configuration,updated_at=now();